def _parse_date(value: Any) -> Optional[date]:
    """Parse a JSON date value.

    ``date``/``datetime`` instances pass through; strings must be ISO
    ``YYYY-MM-DD`` or full ISO 8601 date-times. Values that are not dates
    (including ``None``) return ``None``; malformed date strings raise so
    that bad data is never silently compared.
    """
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if not isinstance(value, str):
        return None
    text = value.strip()
    try:
        return date.fromisoformat(text)
    except ValueError:
        pass
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
    except ValueError as exc:
        raise ValueError(f"not a valid ISO date: {value!r}") from exc

